// DEV_RIO_702 X(Twitter)投稿【下書き準備のみ・dry-run】。
// DEV_RIO_103 の出力を受け取る。103には title フィールドが無いため theme を話題ヒントに使う。
// qa_status が無い手動テスト時は 'PASS' 扱い（実チェインでは103が必ず設定する）。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-x-001',
  theme: i.theme ?? '（テーマ未設定）',
  note_body: i.note_body ?? i.note_draft_body ?? '',
  threads_post: i.threads_post ?? '',
  qa_status: i.qa_status ?? 'PASS',
  platform: 'x',
  action_type: 'prepare_x_drafts'
} }];

// X投稿の下書き生成プロンプトを Anthropic body オブジェクトとして組み立てる。
// テキストはJS文字列に安全に埋め込む（jsonBodyへの直接文字列補間は壊れやすいため回避）。
const i = $input.first().json;
const excerpt = String(i.note_body || '').slice(0, 500);
const prompt = `以下の記事から、X(Twitter)投稿の下書きを3パターン作成してください。\n\nテーマ: ${i.theme}\n本文抜粋: ${excerpt}\n\n条件:\n- 各140字以内、日本語。\n- ハッシュタグ2〜3個。\n- 誇張・虚偽の数値・断定的な成果保証は禁止。\n- 出力は次のJSON配列のみ（前後に説明・コードブロック記号を付けない）:\n[{"angle":"string","text":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 1024,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。失敗時は捏造せず parse_error を明示。冪等性キー付与。公開直前で停止。
const input = $input.first().json;
const ctx = $('Collect Inputs').first().json;
let drafts = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    drafts = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(drafts) || drafts.length === 0) throw new Error('drafts missing/empty');
    drafts = drafts.map(d => ({ angle: d.angle ?? '', text: d.text ?? '' }));
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) drafts = [{ angle: 'manual', text: '（AI応答の取得/解析に失敗。手動で下書きを作成してください）' }];
const idempotency_key = [ctx.platform, ctx.content_id, ctx.action_type].join('|');
return [{ json: {
  content_id: ctx.content_id,
  platform: 'x',
  drafts,
  draft_count: drafts.length,
  idempotency_key,
  state: 'WAITING_APPROVAL',
  published: false,
  draft_error: parse_error,
  note: 'dry-run。X投稿の下書き候補のみ生成。★自動投稿はしない。人間が内容を確認し、問題なければ手動でXに投稿する（CLAUDE.md 準拠）。'
} }];

// QAゲート不通過（qa_status != PASS）。下書き生成をスキップ。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id,
  platform: 'x',
  skipped: true,
  qa_status: i.qa_status,
  state: 'SKIPPED_NOT_PASS',
  published: false,
  note: 'qa_status が PASS ではないため X下書き生成をスキップ（品質未達コンテンツは配布準備しない）。'
} }];
